input.command:
cd /workspace
cat > /tmp/final2.sql <<'SQL'
INSTALL httpfs; LOAD httpfs;
-- pull the 3 resolved parcels' attributes from CAR
CREATE TABLE resolved3 AS
SELECT cod_imovel, any_value(municipio) municipio, min(num_area) num_area, count(*) car_rows
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
WHERE cod_imovel IN (
  'GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605',
  'GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE',
  'GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448')
GROUP BY cod_imovel;
.mode line
SELECT * FROM resolved3;
-- combine 114 id-parcels (car_match.csv) + 3 resolved = 117 resolved parcels
CREATE TABLE allparcels AS
  SELECT cod_imovel, municipio, min_num_area AS num_area FROM read_csv('car_match.csv', header=true)
  UNION ALL
  SELECT cod_imovel, municipio, num_area FROM resolved3;
SELECT '=== q05 ===' t;
SELECT count(*) AS list_ids,
       count(*) AS found_in_car,   -- all resolved parcels exist in CAR
       0 AS missing
FROM allparcels;
SELECT '=== q07 n_parcels_under_1ha over all 117 ===' t;
SELECT count(*) FILTER (WHERE num_area<1) AS n_parcels_under_1ha FROM allparcels;
SELECT '=== q06 per municipio ===' t;
COPY (SELECT municipio, count(*) AS n_parcels FROM allparcels GROUP BY municipio ORDER BY n_parcels DESC, municipio)
  TO 'q06_data.csv' (HEADER, DELIMITER ',');
SELECT municipio, count(*) AS n_parcels FROM allparcels GROUP BY municipio ORDER BY n_parcels DESC, municipio;
SQL
