INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy=true;
-- 117 resolved parcel ids
CREATE TEMP TABLE ids117(cod_imovel VARCHAR);
INSERT INTO ids117
  SELECT DISTINCT cod_imovel FROM read_csv('lists/goias-sample.csv', header=true, all_varchar=true)
  WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
INSERT INTO ids117 VALUES
  ('GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605'),
  ('GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE'),
  ('GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448');
-- fetch geometries from CAR (one row per parcel; take first if multiple)
CREATE TABLE parcels AS
SELECT cod_imovel, any_value(municipio) AS municipio, any_value(num_area) AS num_area,
       any_value(geometry) AS geom
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
WHERE cod_imovel IN (SELECT cod_imovel FROM ids117)
GROUP BY cod_imovel;
SELECT count(*) AS n_parcels FROM parcels;
-- envelope of the union (bbox)
CREATE TABLE env AS SELECT ST_Extent(ST_Union_Agg(geom)) AS e,
  min(ST_XMin(geom)) xmin, min(ST_YMin(geom)) ymin, max(ST_XMax(geom)) xmax, max(ST_YMax(geom)) ymax
  FROM parcels;
.mode line
SELECT xmin,ymin,xmax,ymax FROM env;
SQL
