input.command:
cd /workspace
cat > /tmp/catch.sql <<'SQL'
LOAD spatial; SET geometry_always_xy=true;
.mode box
SELECT ST_GeometryType(geom) gtype, count(*) n FROM fac WHERE tier='gravity_catchment' GROUP BY 1;
SELECT ST_GeometryType(geom) gtype, count(*) n FROM fac WHERE tier IN ('mill_point','slaughter_point','membership_muni','intake_point') GROUP BY 1;
-- do flagged parcels fall inside any gravity_catchment polygon?
SELECT fl.cod_imovel, count(*) AS catchments_containing
FROM flagged2 fl JOIN parcels_m p USING (cod_imovel)
JOIN fac c ON c.tier='gravity_catchment' AND ST_Intersects(ST_Transform(c.geom,'EPSG:4326','EPSG:5880'), p.gm)
GROUP BY 1 ORDER BY 2 DESC LIMIT 5;
SQL
duckdb work.duckdb < /tmp/catch.sql 2>&1 | tail -25
